sys_script_include.script:
var MediaReviewFilterUtil = Class.create();
MediaReviewFilterUtil.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getUnreviewedMedia: function() {
        var reviewedMediaIds = [];

        var reviewGr = new GlideRecord('x_1092529_sharkf_0_review');
        reviewGr.addQuery('media', '!=', '');
        reviewGr.query();

        while (reviewGr.next()) {
            var mediaId = reviewGr.getValue('media');

            if (mediaId) {
                reviewedMediaIds.push(mediaId.toString());
            }

        }

        if (reviewedMediaIds.length > 0) {
            return 'sys_idNOT IN' + reviewedMediaIds.join(',');
        }

        return '';
    },

    type: 'MediaReviewFilterUtil'
});
